        architectural_signals.append("system")
    if re.search(r"\bscalable\b", text):
        score += 5
        architectural_signals.append("scalable")
    system_relevance = "high" if concepts or architectural_signals else "low"
    reusable_components = []
    for c in concepts:
        reusable_components.append(f"component:{c}")
    for a in architectural_signals:
        reusable_components.append(f"signal:{a}")
    inclusion_reason = "detected concepts: " + ", ".join(concepts) if concepts else "no concepts detected"
    return {
