                existing = seen.get(publication.id)
                if existing is None:
                    seen[publication.id] = publication
                    continue

                existing_size = (
                    len(existing.title)
                    + len(existing.abstract)
                    + sum(len(author) for author in existing.authors)
                    + sum(len(category) for category in existing.categories)
                )
                publication_size = (
                    len(publication.title)
                    + len(publication.abstract)
                    + sum(len(author) for author in publication.authors)
                    + sum(len(category) for category in publication.categories)
                )

                if publication_size > existing_size:
                    seen[publication.id] = publication

        results: List[Dict[str, Any]] = []

        for publication in seen.values():
            analysis = self.analyzer.analyze(publication)
            score = self.scorer.score(publication, analysis)
            publication_dict = asdict(publication)

            results.append(
                {
                    "url": publication_dict["url"],
                    "title": publication_dict["title"],
                    "authors": publication_dict["authors"],
                    "summary": publication_dict["abstract"],
                    "categories": publication_dict["categories"],
                    "detected_technologies": analysis["concepts"],
                    "relevance_score": score["score"],
                    "inclusion_reason": score["inclusion_reason"],
                    "system_relevance": score["system_relevance"],
                    "reusable_components": score["reusable_components"],
                }
            )

        return results

def main() -> None:
    try:
        if len(sys.argv) != 2:
            raise ValueError("Expected exactly one URL argument")

        pipeline = Pipeline(sys.argv[1])
        results = pipeline.run()

        print(
            json.dumps(
                {
                    "ok": True,
                    "results": results,
                },
                ensure_ascii=False,
            )
        )
    except Exception as error:
        print(
            json.dumps(
                {
                    "ok": False,
                    "error_type": type(error).__name__,
                    "error_message": str(error),
                    "traceback": traceback.format_exc(),
                },
                ensure_ascii=False,
            )
        )
        sys.exit(1)

if __name__ == "__main__":
    main()
